import {stepGarden} from '../../../../src/js/garden/GardenSimulation.js';
import {gardenPlatforms,GARDEN as C} from '../../../../src/js/garden/GardenLevel.js';
/** Planejamento usa a física real e comandos possíveis, sem teleporte ou invulnerabilidade. */
export function createPilot(){
 let held=false,target=null,launchX=0,flightAxis=1,flightHold=.85,launchTime=0;
 return s=>{
  const p=s.player,platforms=gardenPlatforms(s.time,s,p.x,800),current=platforms.find(v=>v.id===p.support);
  if(s.stage!=='RUNNING')return{x:0,jump:false};
  if(!p.onGround)return{x:flightAxis,jump:held&&s.time-launchTime<flightHold};
  if(held){held=false;return{x:0,jump:false};}
  target=null;
  const edge=current?current.x+current.w:p.x;
  const enemy=s.enemies.filter(e=>e.alive&&Math.abs(e.x-p.x)<170&&Math.abs(e.y-p.y)<160).sort((a,b)=>a.x-b.x)[0];
  if(current&&!current.rotating&&edge-p.x>42&&!enemy)return{x:1,jump:false};
  // Testa quatro intensidades de direção e diferentes durações do salto.
  let best=null;
  for(const axis of [1,.8,.6,0,-.65,-1])for(const hold of [.85,.5,.28]){
   const clone=structuredClone(s);let landed=null,maxX=p.x;
   for(let t=0;t<1.5;t+=1/30){stepGarden(clone,{x:axis,jump:t<hold},1/30);maxX=Math.max(maxX,clone.player.x);if(clone.stage==='GAME_OVER'||clone.stage==='RESCUING'||clone.stage==='DISORIENTED')break;if(t>.15&&clone.player.onGround){landed=clone.player;break;}}
   const landing=landed?platforms.find(v=>v.id===landed.support):null,safe=!landing?.aerial||(landed.x>=landing.x+30&&landed.x<=landing.x+landing.w-30);
   if(landed&&safe&&landed.x>p.x+30&&!(current?.rotating&&landed.support.startsWith(current.wheelId+'-'))){const threat=enemy?clone.enemies.find(e=>e.id===enemy.id):null;const score=landed.x-(landed.support===p.support?100:0)+(clone.hp-s.hp)*700+(threat?(enemy.hp-threat.hp)*300:0);if(!best||score>best.score)best={score,axis,hold,landed};}
  }
  if(best){held=true;launchX=p.x;flightAxis=best.axis;flightHold=best.hold;launchTime=s.time;target=platforms.find(v=>v.id===best.landed.support)??null;return{x:best.axis,jump:true};}
  if(current?.rotating)return{x:Math.max(-.6,Math.min(.6,(current.x+current.w/2-p.x)/60)),jump:false};
  if(current&&edge-p.x>10)return{x:1,jump:false};
  return{x:0,jump:false};
 };
}
